using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

namespace McpServer;

// MCP SDK discovers tools by scanning for [McpServerToolType] classes.
// Each [McpServerTool] method becomes a callable tool exposed to the LLM.
// Constructor parameters are resolved from DI — the SDK instantiates this
// class per-call using the service provider.
[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _http;

    // The SDK resolves this via DI. Register a named/typed HttpClient
    // in Program.cs and it gets injected here automatically.
    public WeatherTools(HttpClient http)
    {
        _http = http;
    }

    [McpServerTool(Name = "get_forecast")]
    [McpServerToolDescription("Get the weather forecast for a US city using latitude and longitude.")]
    public async Task<string> GetForecastAsync(
        [McpServerToolParameter(Description = "Latitude (e.g. 39.7456)")] double latitude,
        [McpServerToolParameter(Description = "Longitude (e.g. -97.0892)")] double longitude)
    {
        // NWS API: resolve grid point, then fetch forecast
        var pointUrl = $"https://api.weather.gov/points/{latitude},{longitude}";
        var point = await _http.GetFromJsonAsync<PointResponse>(pointUrl);

        if (point?.Properties?.ForecastUrl is null)
            return "Could not resolve forecast location for the given coordinates.";

        var forecast = await _http.GetFromJsonAsync<ForecastResponse>(point.Properties.ForecastUrl);

        if (forecast?.Properties?.Periods is not { Count: > 0 })
            return "No forecast data available.";

        return string.Join("\n---\n", forecast.Properties.Periods.Take(5).Select(p =>
            $"{p.Name}: {p.Temperature}°{p.TemperatureUnit} — {p.DetailedForecast}"));
    }

    [McpServerTool(Name = "get_alerts")]
    [McpServerToolDescription("Get active weather alerts for a US state (two-letter code, e.g. CA).")]
    public async Task<string> GetAlertsAsync(
        [McpServerToolParameter(Description = "Two-letter US state code (e.g. CA, TX)")] string state)
    {
        var url = $"https://api.weather.gov/alerts/active?area={state}";
        var alerts = await _http.GetFromJsonAsync<AlertResponse>(url);

        if (alerts?.Features is not { Count: > 0 })
            return $"No active alerts for {state}.";

        return string.Join("\n---\n", alerts.Features.Take(5).Select(f =>
            $"{f.Properties.Event} ({f.Properties.Severity})\n" +
            $"  Area: {f.Properties.AreaDesc}\n" +
            $"  {f.Properties.Headline}"));
    }
}

// --- JSON response models for the NWS API ---

public record PointResponse(
    [property: JsonPropertyName("properties")] PointProperties? Properties);

public record PointProperties(
    [property: JsonPropertyName("forecast")] string? ForecastUrl);

public record ForecastResponse(
    [property: JsonPropertyName("properties")] ForecastProperties? Properties);

public record ForecastProperties(
    [property: JsonPropertyName("periods")] List<ForecastPeriod>? Periods);

public record ForecastPeriod(
    [property: JsonPropertyName("name")] string Name,
    [property: JsonPropertyName("temperature")] int Temperature,
    [property: JsonPropertyName("temperatureUnit")] string TemperatureUnit,
    [property: JsonPropertyName("detailedForecast")] string DetailedForecast);

public record AlertResponse(
    [property: JsonPropertyName("features")] List<AlertFeature>? Features);

public record AlertFeature(
    [property: JsonPropertyName("properties")] AlertProperties Properties);

public record AlertProperties(
    [property: JsonPropertyName("event")] string Event,
    [property: JsonPropertyName("severity")] string Severity,
    [property: JsonPropertyName("areaDesc")] string AreaDesc,
    [property: JsonPropertyName("headline")] string? Headline);

